    #[test]
    fn generate_with_bodies_emits_namespace_objects() {
        let root = fixture_root("w3cos_esm_codegen_namespace");
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::write(
            root.join("src/nsmod.js"),
            r#"export class Widget {
  describe() { return "widget"; }
}
export function greet(name) { return "hi " + name; }
export const version = "1.0";
export const helper = greet;
export * from "./extra.js";"#,
        )
        .unwrap();
        std::fs::write(root.join("src/extra.js"), r#"export const extra = 7;"#).unwrap();
        std::fs::write(
            root.join("src/app.ts"),
            r#"import * as ns from "./nsmod.js";
export function boot() {
  const w = new ns.Widget();
  const message = ns.greet("bob") + ns.version + ns.helper("x") + ns.extra;
  return w;
}"#,
        )
        .unwrap();

        let resolver = EsmResolver::new(&root);
        let parsed = resolver
            .parse_graph_from_entry(&root.join("src/app.ts"))
            .unwrap();
        let bundle = EsmBundle::build(&parsed, &resolver, &root.join("src/app.ts"));
        assert!(
            bundle.is_fully_resolved(),
            "unresolved: {:?}",
            bundle.unresolved
        );
        let code = generate_with_bodies(&bundle);

        // Namespace accessor: lazy thread-local singleton building an object.
        assert!(
            code.contains("pub fn m2_ns_ns() -> w3cos_core::Value"),
            "namespace accessor fn: {code}"
        );
        assert!(
            code.contains("let mut props = ::std::collections::HashMap::new();"),
            "namespace props map: {code}"
        );
        // Class export → class accessor value.
        assert!(
            code.contains("props.insert(\"__w3cos_getter_Widget\".to_string()")
                && code.contains("move |_, _| super::m1::m1_Widget()"),
            "class prop: {code}"
        );
        // Plain function export → stable interned function object.
        assert!(
            code.contains("props.insert(\"__w3cos_getter_greet\".to_string()")
                && code.contains("move |_, _| super::m1::m1_greet_value()"),
            "function prop: {code}"
        );
        // Variable export → live getter through the _get accessor.
        assert!(
            code.contains("props.insert(\"__w3cos_getter_version\".to_string()")
                && code.contains("move |_, _| super::m1::m1_version_get()"),
            "variable prop: {code}"
        );
        // Alias export (`export const helper = greet`) resolves to the aliased fn.
        assert!(
            code.contains("props.insert(\"__w3cos_getter_helper\".to_string()")
                && code.contains("move |_, _| super::m1::m1_greet_value()"),
            "alias prop: {code}"
        );
        // Star re-export (`export * from`) is included.
        assert!(
            code.contains("props.insert(\"__w3cos_getter_extra\".to_string()")
                && code.contains("move |_, _| super::m0::m0_extra_get()"),
            "star re-export prop: {code}"
        );
        // Bare `ns` in the importing module resolves through the module-local
        // alias. Construction, calls, and reads are covered by the generated
        // bundle semantic test instead of pinning a particular Rust emission.
        assert!(
            code.contains("pub use self::m2_ns_ns as ns;"),
            "namespace alias: {code}"
        );
        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn generated_skeleton_compiles_as_valid_rust() {
        let root = fixture_root("w3cos_esm_codegen_compiles");
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::write(
            root.join("src/app.ts"),
            r#"import { Theme } from "my-lib";
export function boot() {}"#,
        )
        .unwrap();

        let lib = root.join("node_modules/my-lib");
        std::fs::create_dir_all(&lib).unwrap();
        std::fs::write(lib.join("package.json"), r#"{"main":"index.js"}"#).unwrap();
        std::fs::write(
            lib.join("index.js"),
            r#"export class Theme {}
export function makeTheme() {}"#,
        )
        .unwrap();

        let resolver = EsmResolver::new(&root);
        let parsed = resolver
            .parse_graph_from_entry(&root.join("src/app.ts"))
            .unwrap();
        let bundle = EsmBundle::build(&parsed, &resolver, &root.join("src/app.ts"));
        let code = generate_skeleton(&bundle);

        // Write the skeleton to a file and type-check it with rustc.
        let rs_path = root.join("skeleton.rs");
        let wrapper =
            format!("#![allow(dead_code, unused_imports, clippy::all)]\nfn main() {{}}\n{code}");
        std::fs::write(&rs_path, wrapper).unwrap();

        let output = std::process::Command::new("rustc")
            .arg("--edition=2021")
            .arg("--emit=metadata")
            .arg("--crate-type=bin")
            .arg("-o")
            .arg(root.join("skeleton_meta"))
            .arg(&rs_path)
            .output()
            .expect("rustc should be available");

        assert!(
            output.status.success(),
            "generated skeleton should compile.\n--- code ---\n{code}\n--- stderr ---\n{}",
            String::from_utf8_lossy(&output.stderr)
        );

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn generate_with_bodies_lowers_function_code() {
        let root = fixture_root("w3cos_esm_codegen_bodies");
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::write(
            root.join("src/app.ts"),
            r#"import { EditorView } from "@codemirror/view";
export function boot() {
  const view = new EditorView({});
  return view;
}
export const identity = (value) => value;
export const readSize = ({height: h, width: w = 10}) => h + w;"#,
        )
        .unwrap();

        let view = root.join("node_modules/@codemirror/view");
        std::fs::create_dir_all(view.join("dist")).unwrap();
        std::fs::write(view.join("package.json"), r#"{"module":"dist/index.js"}"#).unwrap();
        std::fs::write(
            view.join("dist/index.js"),
            r#"export class EditorView {
  mount() {
    const el = document.createElement("div");
    return el;
  }
}"#,
        )
        .unwrap();

        let resolver = EsmResolver::new(&root);
        let parsed = resolver
            .parse_graph_from_entry(&root.join("src/app.ts"))
            .unwrap();
        let bundle = EsmBundle::build(&parsed, &resolver, &root.join("src/app.ts"));
        let code = generate_with_bodies(&bundle);

        // Ordinary functions and function-valued variables share the W3IR AOT
        // backend rather than a second direct-AST semantic implementation.
        // Constructor behavior is exercised by generated bundle tests; this
        // structural test only checks that the W3IR backend owns the function.
        assert!(
            code.contains("synchronous function boot compiled from W3IR"),
            "boot should lower through W3IR: {code}"
        );
        assert!(
            code.contains("synchronous function identity compiled from W3IR")
                && code.contains("__args.get(0).cloned()")
                && code.contains("identity_set(value: w3cos_core::Value)"),
            "top-level arrows should lower to callable W3IR functions: {code}"
        );
        assert!(
            code.contains("synchronous function readSize compiled from W3IR"),
            "destructured-parameter function should lower through W3IR: {code}"
        );
        // Class method body should be lowered into a free `__m_` function
        assert!(
            code.contains("fn m0_EditorView__m_mount(__this: w3cos_core::Value")
                && code.contains("class member EditorView.mount compiled from W3IR"),
            "method body should be lowered through W3IR: {code}"
        );
        // Should NOT have todo!() for functions that have bodies
        assert!(
            !code.contains("todo!(\"lower ESM body: boot\")"),
            "boot body should be lowered: {code}"
        );

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
